import {defaults,metrics,effective,meteredEV} from './physics.mjs';
export const portraitExample={...defaults,focal:70,aperture:1.4,mode:'A',subject:4,focus:4,foreground:2.4,background:18,sculpture:20,ballX:3,birdX:3,waveSpeed:0,ballSpeed:0,birdSpeed:0,bokehLights:false,rayTargets:'person,background',grid:false};
export const bokehExample={...portraitExample,focal:85,scene:'night',ev:7,temperature:3800,wb:3800,bokehLights:true,clearBackdrop:true,subject:5,focus:5,background:30,aperture:1.4,pupilShape:'iris',bladeCount:5};
export const motionExample={...portraitExample,focal:50,aperture:4,mode:'S',autoISO:true,time:1/15,speed:0,waveSpeed:4,ballSpeed:0,birdSpeed:0,motion:true};
const scene=(patch={})=>({...portraitExample,...patch});
export const tourSteps=[
 {id:'focus',target:'focus',view:'camera',title:['Die Person scharf stellen','Bring the person into focus'],task:['Stelle Fokusdistanz auf 4,0 m — oder klicke die Person im Aufnahmebild an.','Set Focus distance to 4.0 m — or click the person in the captured image.'],success:['Die Person ist scharf. Der Hintergrund bei 18 m bleibt unscharf.','The person is sharp. The background at 18 m stays blurred.'],why:['Fokus legt fest, welche Entfernung exakt auf den Sensor abgebildet wird. Er macht nicht alle Entfernungen gleichzeitig scharf.','Focus sets which distance is imaged exactly onto the sensor. It does not make all distances sharp at once.'],start:scene({focus:2}),end:{focus:4},check:s=>Math.abs(effective(s).focus-(s.subject+s.cameraBack))<.15},
 {id:'aperture',target:'aperture',view:'camera',title:['Öffnung kleiner, Schärfebereich größer','Smaller opening, greater depth of field'],task:['Ziehe die Blende auf ƒ/8 oder höher. Vergleiche den Hintergrund und den Strahlenkegel.','Set Aperture to f/8 or higher. Compare the background and the ray cone.'],success:['Die engere Öffnung verkleinert Unschärfeflecken. Die Automatik hat dafür die Belichtungszeit verlängert.','The narrower opening reduces blur spots. Automatic exposure has lengthened the shutter time.'],why:['Die Person bleibt im Fokus. Mehr Umgebung erscheint scharf. Gleiche Helligkeit hat einen Preis: längere Zeit kann bewegte Motive verwischen. „Zeit: Auto“ gleicht hier aus.','The person stays in focus. More surroundings look sharp. Keeping brightness has a cost: a longer exposure can blur moving subjects. Shutter Auto compensates here.'],start:scene(),end:{aperture:8},check:s=>effective(s).aperture>=7.95},
 {id:'zoom',target:'focal',view:'camera',title:['Zoomen, ohne die Kamera zu bewegen','Zoom without moving the camera'],task:['Ändere nur Brennweite von 35 auf 85 mm. Lass die Kamera im Raumplan an ihrem Platz.','Change only Focal length from 35 to 85 mm. Leave the camera in its position in the scene plan.'],success:['Du siehst einen engeren Ausschnitt. Der Standpunkt und die Perspektive blieben gleich.','You see a tighter crop. The viewpoint and perspective stayed the same.'],why:['Die Person wird größer im Bild. Bewegen der Kamera ist ein anderer Vorgang: Dabei ändern sich auch die Größenverhältnisse zwischen nahen und fernen Motiven.','The person becomes larger in the frame. Moving the camera is different: it changes relative sizes of near and distant subjects.'],start:scene({focal:35,aperture:4}),end:{focal:85},check:s=>s.focal>=85&&s.cameraBack===0},
 {id:'motion',target:'time',view:'controls',title:['Die winkende Hand einfrieren','Freeze the waving hand'],task:['Stelle Belichtungszeit auf 1/1000 s oder kürzer. Die Person bleibt stehen; nur der Arm winkt.','Set Shutter speed to 1/1000 s or faster. The person stays in place; only the arm waves.'],success:['Die Bewegungsspur am Arm wird kürzer. Auto-ISO steigt gegebenenfalls: weniger Licht kann mehr Körnung bedeuten.','The arm’s motion trail is shorter. Auto ISO may rise: less light can mean more grain.'],why:['Es gibt keine allgemein richtige Zeit. Hier ist „Hand einfrieren“ das Ziel. Für eine absichtliche Bewegungsspur wäre eine längere Zeit richtig.','There is no universally correct shutter speed. Here the goal is to freeze the hand. For an intentional motion trail, a longer time would be appropriate.'],start:motionExample,end:{time:1/1000},check:s=>effective(s).time<=1/1000},
 {id:'night',target:'auto-setup',view:'controls',title:['Automatik löst nicht jeden Zielkonflikt','Automatic exposure has trade-offs'],task:['Klicke „Automatik ein“. Vergleiche danach ISO und Belichtungszeit mit der dunklen Ausgangsaufnahme.','Click “Enable auto”. Then compare ISO and shutter speed with the dark initial capture.'],success:['Die Aufnahme wird heller. Prüfe die Körnung: Die Automatik trifft einen Kompromiss, sie liefert kein kostenlos perfektes Bild.','The capture is brighter. Inspect the grain: automatic exposure chooses a compromise, not a free perfect image.'],why:['Mehr Zeit sammelt mehr Licht, aber auch Bewegung. Eine größere Öffnung begrenzt die Schärfentiefe. ISO verstärkt das Signal; es sammelt keine zusätzlichen Photonen.','More time collects more light, but also motion. A larger opening limits depth of field. ISO amplifies the signal; it collects no extra photons.'],start:scene({scene:'night',ev:5,temperature:3800,wb:3800,aperture:4,time:1/125,mode:'M'}),end:{mode:'P',autoISO:true,autoFocus:true,autoWB:true},check:s=>(s.mode!=='M'||s.autoISO)&&Math.abs(metrics(s).offset+meteredEV(effective(s))-s.ev-s.comp)<.4},

 {id:'lighting',target:'windowEV',view:'light',title:['Eigenlicht im Hintergrund','Light sources in the background'],task:['Erhöhe Fensterhelligkeit auf mindestens 10 EV. Umgebungslicht und Belichtung bleiben gleich.','Raise Window brightness to at least 10 EV. Ambient light and exposure stay the same.'],success:['Die Fenster leuchten heller, ohne die gesamte Umgebung aufzuhellen.','The windows glow brighter without brightening the whole environment.'],why:['Fenster und Lichterkette haben eigene Helligkeitsregler. +1 EV verdoppelt ihre Eigenhelligkeit. Sie werfen in diesem vereinfachten Modell kein Licht auf andere Objekte; Laterne und Spot tun das.','Windows and string lights have independent brightness controls. +1 EV doubles their emission. In this simplified model they do not illuminate other objects; the streetlamp and spotlight do.'],start:{...portraitExample,scene:'night',ev:6,focal:50,aperture:4,temperature:3800,wb:3800,windowsOn:true,windowEV:5,bokehLights:true,bokehEV:5,clearBackdrop:true,mode:'M',time:1/8},end:{windowEV:11},check:s=>s.windowEV>=10},
 {id:'pupil',target:'aperture',view:'optics',detail:'aperture',title:['Aus kleinen Lampen werden Lichtflecken','Small bulbs become blur spots'],task:['Wähle „Gerundete Lamellen“. Vergleiche die fünfeckigen Flecken der Lichterkette mit den runderen Flecken danach.','Enable “Rounded blades”. Compare the string lights’ pentagonal spots with the rounder spots afterwards.'],success:['Öffnung und Lichtfleck werden runder. Die Flecken gehören zu den kleinen Lampen im Hintergrund bei 30 m.','Both opening and blur spot become rounder. The spots come from the small bulbs in the background at 30 m.'],why:['Die Person bei 5 m ist fokussiert, die Lichterkette nicht. Ein kleines helles Motiv zeigt bei Defokus näherungsweise die Form der Öffnung. Das funktioniert auch bei Tageslicht — etwa mit glitzernden Reflexen.','The person at 5 m is focused; the string lights are not. A small bright subject approximately shows the opening’s shape when defocused. This also works in daylight, for example with sparkling reflections.'],start:{...bokehExample},end:{roundedBlades:true},check:s=>s.pupilShape==='iris'&&s.roundedBlades},
 {id:'curtains',target:'time',view:'optics',detail:'shutter',title:['Wie entstehen 1/1000 Sekunde?','How does 1/1000 second happen?'],task:['Stelle Belichtungszeit auf 1/1000 s. Spiele den Ablauf ab: Achte auf die markierte mittlere Sensorzeile.','Set Shutter speed to 1/1000 s. Play the sequence and watch the highlighted middle sensor row.'],success:['Der zweite Vorhang folgt früher. Die mittlere Zeile bleibt nur 1/1000 s offen, obwohl beide Vorhänge länger unterwegs sind.','The second curtain follows sooner. The middle row stays open for only 1/1000 s, although both curtains take longer to cross.'],why:['Erster Vorhang: Licht freigeben. Zweiter Vorhang: wieder verdecken. Kürzere Zeit bedeutet hier einen kleineren Startabstand bei gleicher Laufgeschwindigkeit.','First curtain: uncover the sensor. Second curtain: cover it again. A shorter time here means a shorter delay at the same travel speed.'],start:{...motionExample,time:1/30},end:{time:1/1000},check:s=>effective(s).time<=1/1000}
];
