export function interpolatedDemo(step,progress,reduced=false){const p=reduced?(progress>=.55?1:0):Math.min(1,Math.max(0,step.id==='curtains'?(progress-.40)/.12:(progress-.16)/.62)),q=p*p*(3-2*p),out={...step.start};for(const [key,value]of Object.entries(step.end)){const initial=step.start[key];out[key]=typeof value==='number'?(value>0&&initial>0&&['aperture','time','iso','focus','focal'].includes(key)?Math.exp(Math.log(initial)+(Math.log(value)-Math.log(initial))*q):initial+(value-initial)*q):q<.5?initial:value;}if(reduced)out.motion=false;return out;}


export function demoShutterPhase(p){return p<.36?p/.36:p<.52?1:p<.90?(p-.52)/.38:1;}
